pub fn write(&mut self, bytes: &[u8]) -> Result<()> {
        let raw = self.raw()?;
        let database = self.database.clone();
        let _guard = database.lock();
        let request = zova_sys::zova_object_writer_write_request {
            writer: raw.as_ptr(),
            data: bytes.as_ptr(),
            len: bytes.len(),
        };
        database.status_locked(unsafe { zova_sys::zova_object_writer_write(&request) })
    }

pub fn finish(mut self) -> Result<ObjectId> {
        let raw = self.raw()?;
        let database = self.database.clone();
        let _guard = database.lock();
        let mut out = zova_sys::zova_object_id { bytes: [0; 32] };
        let request = zova_sys::zova_object_writer_finish_request {
            writer: raw.as_ptr(),
            out_id: &mut out,
        };
        database.status_locked(unsafe { zova_sys::zova_object_writer_finish(&request) })?;
        self.destroy_locked();
        Ok(from_c_object_id(out))
    }

pub fn cancel(mut self) -> Result<()> {
        let raw = self.raw()?;
        let database = self.database.clone();
        let _guard = database.lock();
        let request = zova_sys::zova_object_writer_cancel_request {
            writer: raw.as_ptr(),
        };
        database.status_locked(unsafe { zova_sys::zova_object_writer_cancel(&request) })?;
        self.destroy_locked();
        Ok(())
    }

fn destroy(&mut self) {
        if self.raw.is_none() {
            return;
        }
        let database = self.database.clone();
        let _guard = database.lock();
        self.destroy_locked();
    }

pub fn read(&mut self, buffer: &mut [u8]) -> Result<usize> {
        let raw = self.raw()?;
        let database = self.database.clone();
        let _guard = database.lock();
        let mut read = 0;
        let request = zova_sys::zova_object_reader_read_request {
            reader: raw.as_ptr(),
            buffer: buffer.as_mut_ptr(),
            buffer_len: buffer.len(),
            out_read: &mut read,
        };
        database.status_locked(unsafe { zova_sys::zova_object_reader_read(&request) })?;
        Ok(read)
    }

pub fn close(&mut self) -> Result<()> {
        if self.raw.is_none() {
            return Ok(());
        }
        let database = self.database.clone();
        let _guard = database.lock();
        self.destroy_locked(true)
    }

fn destroy(&mut self) {
        if self.raw.is_none() {
            return;
        }
        let database = self.database.clone();
        let _guard = database.lock();
        let _ = self.destroy_locked(false);
    }

